CREATE OR REPLACE FUNCTION public.dec_contestation_48h() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = public AS $$ DECLARE v_valide_le TIMESTAMPTZ; BEGIN IF NEW.presence_id IS NULL THEN RETURN NEW; END IF; SELECT valide_le INTO v_valide_le FROM presences WHERE id = NEW.presence_id; IF v_valide_le IS NULL THEN RETURN NEW; END IF; IF v_valide_le + INTERVAL '48 hours' < NOW() THEN RETURN NEW; END IF; RETURN NEW; END; $$; NOTIFY pgrst, 'reload schema'